/**
 * Offline support registration.
 *
 * The service worker is generated by vite-plugin-pwa (autoUpdate). This
 * wrapper is the only place in the app that registers it, and it refuses to
 * register inside previews, iframes and development, so the Lovable editing
 * experience is never cached. `?sw=off` unregisters the worker for testing.
 */
import { registerSW } from "virtual:pwa-register";

const PREVIEW_HOST_PATTERN = /^(?:id-preview|preview)(?:-[a-z0-9]+)?--.+/;

const isPreviewHostname = (hostname: string): boolean =>
{
    if (!hostname.endsWith(".lovable.app") && !hostname.endsWith(".gpt-eng.com") && !hostname.endsWith(".gptengineer.run"))
    {
        return false;
    }
    const firstLabel = hostname.split(".")[0];
    return PREVIEW_HOST_PATTERN.test(firstLabel) || /^project--[a-f0-9-]{36}-dev$/.test(firstLabel);
};

const inRefusedContext = (): boolean =>
{
    if (!import.meta.env.PROD) return true;
    try
    {
        if (window.self !== window.top) return true;
    }
    catch
    {
        // A thrown access check means we are inside a cross-origin frame.
        return true;
    }

    const hostname = window.location.hostname.toLowerCase();
    if (isPreviewHostname(hostname)) return true;
    if (hostname === "lovableproject.com" || hostname.endsWith(".lovableproject.com")) return true;
    if (hostname === "lovableproject-dev.com" || hostname.endsWith(".lovableproject-dev.com")) return true;
    if (hostname === "beta.lovable.dev" || hostname.endsWith(".beta.lovable.dev")) return true;
    if (window.location.search.includes("sw=off")) return true;

    return false;
};

export function registerPwa(): void
{
    if (!("serviceWorker" in navigator)) return;

    if (inRefusedContext())
    {
        // Remove any matching stale worker so previews and kill-switch visits stay clean.
        void navigator.serviceWorker
            .getRegistrations()
            .then((registrations) =>
            {
                for (const registration of registrations)
                {
                    if (registration.active?.scriptURL.endsWith("/sw.js"))
                    {
                        void registration.unregister();
                    }
                }
            })
            .catch(() => undefined);
        return;
    }

    registerSW({ immediate: false });
}
